/// Resolve one reference through a provider.  An implementation detail of
/// loadActorModel, not API: a caller with a provider already has parse*.
template <class T, class Fn>
std::optional<T> resolve(const AssetRef& ref, AssetProvider& src, Fn parse) {
    if (!ref.valid()) return std::nullopt;
    auto bytes = src.load(ref.group, ref.id);
    if (bytes.empty()) return std::nullopt;
    return parse(bytes);
}

