std::optional<ActorModel> loadActorModel(std::span<const u8> actorFile,
                                         AssetProvider& src) {
    auto actor = parseActor(actorFile);
    if (!actor) return std::nullopt;
    ActorModel m;
    m.actor = std::move(*actor);
    m.appearance = resolve<Appearances>(m.actor.snoAppearance, src, parseAppearances);
    m.animSet = resolve<AnimSet>(m.actor.snoAnimSet, src, parseAnimSet);
    m.physics = resolve<Physics>(m.actor.snoPhysics, src, parsePhysics);
    return m;
}

